window.filaforgeEditor = (initial, wire) => ({
    libraryOpen:false,structureManager:false,widgetDefinitions:[],sectionItems:[],designTokens:{},repeaterOpen:false,repeaterSource:'',repeaterFields:[],repeaterColumns:3,repeaterBusy:false,revisionOpen:false,revisionItems:[],revisionCompare:null,recovery:null,autosavePaused:false,autosaveTimer:null,customInspector:false,
    scriptsOpen:false,scriptPermissions:{manage:false,gtm:false,custom:false},document: initial.document, version: initial.version, selected: 'root', dirty:false, busy:false, status:'', past:[], future:[], port:null, previewMode:false,previewBusy:false,previewPages:{},flushResolve:null,fonts:[],fontDefault:null,sources:[],dataFormatters:[],dataComponents:[],dataSlots:{},bindingSlot:'',pickerQuery:'',pickerSlot:'',pickerTarget:null,pickerReplace:false,pickerComponent:null,pickerArguments:{},pickerBusy:false,pickerError:'',pickerLoading:true,loopFilterKey:'',loopFilterValue:'', inspectorSections:{content:true,responsive:false,interaction:false,appearance:false,data:false,actions:false,preset:false}, styleClipboard:null,htmlImportOpen:false, htmlSource:'', htmlImportBusy:false, htmlImportError:'', htmlImportWarnings:[], mediaTab:'library', remoteURL:'', remoteKind:'image', device:'desktop', showInspector:true, search:'', context:null, libraryTab:'widgets',presetItems:[],presetCategory:@js(__('filaforge::studio.editor_ui.all')),presetName:'',presetSaving:false,backgroundHex:'#4f46e5',mediaOpen:false,mediaItems:[],mediaURLs:{},mediaSearch:'',mediaKind:'',mediaPage:1,mediaLast:1,mediaTotal:0,mediaBusy:false,mediaError:'',mediaProgress:0,mediaSelected:null,mediaTarget:null,mediaEditing:false,mediaMeta:{},crop:{x:0,y:0,crop_width:1,crop_height:1,rotate:0,width:null}, iconCatalog:{}, iconQuery:'', iconOpen:false, iconLoading:true, draftProps:{}, clipboard:null, widgets:[{type:'dropdown-menu',label:@js(__('filaforge::studio.menu_preset')),icon:''},{type:'menu-item',label:@js(__('filaforge::studio.menu_item')),icon:''},{type:'progress',label:@js(__('filaforge::studio.progress_preset')),icon:''},{type:'wizard',label:@js(__('filaforge::studio.wizard_preset')),icon:''},{type:'wizard-step',label:@js(__('filaforge::studio.wizard_step')),icon:''},{type:'query-loop',label:@js(__('filaforge::studio.data_loop')),icon:''},{type:'shortcode',label:@js(__('filaforge::studio.data_component'