    init() {
        this.compactQuery=window.matchMedia('(max-width:760px)');this.compactListener=event=>{if(event.matches){this.showInspector=false;this.libraryOpen=false}};this.compactListener(this.compactQuery);this.compactQuery.addEventListener('change',this.compactListener);

        if(typeof ResizeObserver!=='undefined'){this.toolbarObserver=new ResizeObserver(entries=>this.$el.style.setProperty('--ff-toolbar-height',entries[0].target.getBoundingClientRect().height+'px'));this.toolbarObserver.observe(this.$el.querySelector('.ff-bar'))}

        this.readRecovery();
        this.mediaCategory='';this.mediaFolder='';this.mediaFolders=[];this.mediaCategories=[];this.mediaChecked=[];this.bulkFolder='';this.bulkCategory='';this.newMediaFolder='';this.draggedNode=null;
        fetch(@js(\FilaForge\Studio\Support\Assets::url('fontawesome.json'))).then(r=>{if(!r.ok)throw new Error();return r.json()}).then(icons=>{this.iconCatalog=icons;this.iconLoading=false;if(this.port){this.port.postMessage({type:'icons',icons});this.render()}}).catch(()=>{this.iconLoading=false;this.status=@js(__('filaforge::studio.editor_ui.icons_load_failed'))});
