    connect() { const channel=new MessageChannel(); this.port=channel.port1; this.port.onmessage=({data})=>{ if(data.type==='ready'){this.port.postMessage({type:'media',urls:JSON.parse(JSON.stringify(this.mediaURLs))});this.port.postMessage({type:'icons',icons:JSON.parse(JSON.stringify(this.iconCatalog))});this.render();}
        if(data.type==='flushed'&&this.flushResolve){const resolve=this.flushResolve;this.flushResolve=null;resolve();}
        if(data.type==='cell'){const n=this.find(data.id);if(n?.type==='table'&&n.props.rows[data.row]?.[data.col]!==undefined&&typeof data.value==='string'&&typeof data.html==='string')this.commit(()=>{n.props.rows[data.row][data.col]=data.value;n.props.formatted={...(n.props.formatted||{}),['cell:'+data.row+':'+data.col]:data.html}});}
        if(data.type==='inline'&&typeof data.value==='string'&&typeof data.html==='string'){const n=this.find(data.id),fields={heading:['text'],text:['text'],'rich-text':['html'],button:['text'],link:['text'],quote:['text','author'],navigation:['brand'],comments:['title','button'],progress:['label'],'dropdown-menu':['brand'],'menu-item':['label'],'faq-item':['question','answer'],table:['caption']};if(n&&fields[n.type]?.includes(data.field)){this.commit(()=>{if(n.type==='rich-text')n.props.html=data.html;else{n.props[data.field]=data.value;n.props.formatted={...(n.props.formatted||{}),[data.field]:data.html}}});this.draftProps=JSON.parse(JSON.stringify(n.props));if(n.type==='heading')wire.set('settings',{text:n.props.text,tag:n.props.tag},false)}}
        if(data.type==='boundField'){this.status=@js(__('filaforge::studio.data_bound_hint'));this.inspectorSections.data=true}
        if(data.type==='inlineUnavailable'){this.status=@js(__('filaforge::studio.editor_ui.inline_unavailable'))}
        if(data.type==='selectedInline'){this.selected=data.id;this.draftProps=JSON.parse(JSON.stringify(this.find(data.id)?.props||{}));}
        if(data.type==='contextAction'){this.selected=data.id;if(data.action==='parent'){const p=this.parentOf(data.id);if(p)this.select(p.id)}else if(data.action==='up')this.move(-1);else if(data.action==='down')this.move(1);else if(['copy','paste','duplicate','remove'].includes(data.action))this[data.action]();}
        if(data.type==='shortcut'){if(data.key==='Delete')this.remove();else if(data.key==='s')this.save();else if(data.key==='d')this.duplicate();else if(data.key==='ArrowUp'&&data.alt)this.move(-1);else if(data.key==='ArrowDown'&&data.alt)this.move(1);else data.shift?this.redo():this.undo();}
 if(data.type==='select'&&typeof data.id==='string')this.select(data.id); if(data.type==='insert'&&(this.widgets.some(w=>w.type===data.widget)||data.widget.startsWith('preset:')))this.insert(data.widget,data.parent);if(data.type==='move')this.moveNode(data.id,data.targetId,data.position);if(data.type==='dragStart')this.draggedNode=data.id;if(data.type==='dragEnd'&&this.draggedNode===data.id)this.draggedNode=null; }; this.$refs.canvas.contentWindow.postMessage('filaforge-connect','*',[channel.port2]); },
    async importHtmlContent(){if(this.htmlImportBusy)return;this.htmlImportBusy=true;this.htmlImportError='';this.htmlImportWarnings=[];try{const result=await wire.importHtml(this.htmlSource);if(result.error){this.htmlImportError=result.error;return}const selected=this.find(this.selected),target=this.insertionParent();if(!target)return;const incoming=result.document.root.children;if(this.nodes().length+JSON.stringify(incoming).split('"widgetVersion"').length-1>1000){this.htmlImportError=@js(__('filaforge::studio.import_limits'));return}this.commit(()=>target.children.push(...incoming));this.htmlImportWarnings=result.warnings;this.htmlSource='';this.status=@js(__('filaforge::studio.import_success'));if(!result.warnings.length)this.htmlImportOpen=false}catch(e){this.htmlImportError=@js(__('filaforge::studio.import_invalid'))}finally{this.htmlImportBusy=false}},
    useRemoteMedia(){const url=this.remoteURL.trim();if(!/^(https?:\/\/[^\s<>]+|\/(?!\/)[^\s<>]*)$/i.test(url)||/[\\\x00-\x20\x7f]/.test(url)){this.mediaError=@js(__('filaforge::studio.remote_invalid'));return}let node=this.find(this.selected);if(this.mediaTarget&&['src','poster'].includes(this.mediaTarget)){this.commit(()=>node.props[this.mediaTarget]=url)}else{const parent=this.insertionParent();if(!parent)return;this.insert(this.remoteKind,parent.id);node=parent.children.at(-1);this.commit(()=>node.props.src=url)}this.select(node.id);this.remoteURL='';this.mediaOpen=false},
    dataLabel(group,key){const labels=@js(collect(__('filaforge::studio'))->filter(fn($v,$k)=>str_starts_with($k,'data_slot_')||str_starts_with($k,'data_format_'))->all());return labels['data_'+group+'_'+key]||key},
    openPageScripts(){this.scriptsOpen=true;this.showInspector=true;this.$nextTick(()=>this.$refs.gtmInput?.focus())},
    setPageScript(key,value){if(!this.scriptPermissions.manage||!['gtm','head','bodyEnd'].includes(key))return;if(key==='gtm'&&!this.scriptPermissions.gtm)return;if(key!=='gtm'&&!this.scriptPermissions.custom)return;value=value.trim();if(key==='gtm')value=value.toUpperCase();if((this.document.integrations?.[key]||'')===value)return;this.commit(()=>{this.document.integrations={...(this.document.integrations||{})};if(value)this.document.integrations[key]=value;else delete this.document.integrations[key];if(!Object.keys(this.document.integrations).length)delete this.document.integrations})},
    flushPageScripts(){if(!this.scriptsOpen||!this.scriptPermissions.manage)return;for(const [key,ref]of Object.entries({gtm:'gtmInput',head:'scriptHead',bodyEnd:'scriptBodyEnd'}))if(this.$refs[ref])this.setPageScript(key,this.$refs[ref].value)},
    addMenuItem(submenu=false){const node=this.find(this.selected);let parent;if(node?.type==='dropdown-menu'||(submenu&&node?.type==='menu-item'))parent=node;else parent=this.parentOf(this.selected);if(!parent||!['dropdown-menu','menu-item'].includes(parent.type)||parent.children.length>=30)return;let ancestor=parent,level=1;while(ancestor?.type==='menu-item'){level++;ancestor=this.parentOf(ancestor.id)}if(level>4)return;const item={id:crypto.randomUUID(),type:'menu-item',widgetVersion:1,props:{label:@js(__('filaforge::studio.menu_item')),url:'#'},styles:[],responsive:[],bindings:[],visibility:[],meta:[],children:[]};this.commit(()=>parent.children.push(item));this.select(item.id)},
    insertionParent(id=this.selected){let node=this.find(id);while(node){if(this.acceptsChildren(node)&&this.canStructure(node))return node;node=this.parentOf(node.id)}return null},
    menuTreeDepth(node){return 1+Math.max(0,...node.children.map(child=>this.menuTreeDepth(child)))},
    validMenuTarget(node,parent){if(!['dropdown-menu','menu-item'].includes(parent?.type)||parent.children.length>=30)return false;let depth=1,ancestor=parent;while(ancestor?.type==='menu-item'){depth++;ancestor=this.parentOf(ancestor.id)}return depth+this.menuTreeDepth(node)-1<=4},
    setMenu(key,value){const node=this.find(this.selected);if(!node||!['dropdown-menu','menu-item'].includes(node.type))return;this.commit(()=>node.props[key]=value);this.draftProps=JSON.parse(JSON.stringify(node.props))},
    setFlow(key,value){const n=this.find(this.selected);if(!n||!['progress','wizard','wizard-step'].includes(n.type))return;this.commit(()=>n.props[key]=value);this.draftProps=JSON.parse(JSON.stringify(n.props))},
    addWizardStep(){const n=this.find(this.selected);if(n?.type!=='wizard'||n.children.length>=12)return;const step={id:crypto.randomUUID(),type:'wizard-step',widgetVersion:1,props:{title:@js(__('filaforge::studio.wizard_step'))+' '+(n.children.length+1)},styles:[],responsive:[],bindings:[],visibility:[],meta:[],children:[]};this.commit(()=>n.children.push(step));this.select(step.id)},
    source(name){return this.sources.find(source=>source.name===name)},
    rowSource(){let n=this.parentOf(this.selected);while(n){if(n.type==='query-loop')return this.source(n.props.provider);n=this.parentOf(n.id)}return null},
    availableSources(){const row=this.rowSource();return row?[{...row,name:'@item',label:@js(__('filaforge::studio.data_item'))},...this.sources]:this.sources},
    binding(){return this.find(this.selected)?.bindings?.[this.bindingSlot]||null},
    fieldsFor(provider){return (provider==='@item'?this.rowSource():this.source(provider))?.fields||{}},
    setBinding(key,value){const n=this.find(this.selected);if(!n||!this.bindingSlot)return;this.commit(()=>{n.bindings={...(n.bindings||{})};if(key==='provider'){if(!value){delete n.bindings[this.bindingSlot];return}n.bindings[this.bindingSlot]={provider:value,field:Object.keys(this.fieldsFor(value))[0]||'',formatter:'text',fallback:''}}else if(n.bindings[this.bindingSlot])n.bindings[this.bindingSlot][key]=value})},
    setVisibility(key,value){const n=this.find(this.selected);if(!n)return;this.commit(()=>{if(key==='provider'){n.visibility=value?{provider:value,field:Object.keys(this.fieldsFor(value))[0]||'',operator:'not_empty',value:null}:[]}else if(n.visibility?.provider)n.visibility[key]=value})},
    setConditionValue(value){const n=this.find(this.selected);const type=this.fieldsFor(n?.visibility?.provider)?.[n?.visibility?.field]?.type;this.setVisibility('value',type==='number'?Number(value):type==='boolean'?value==='true':value)},
    setLoop(key,value){const n=this.find(this.selected);if(n?.type!=='query-loop')return;this.commit(()=>{if(key==='provider'){n.props.provider=value;n.props.query={limit:Math.min(6,this.source(value)?.maxLimit||6)}}else if(key==='emptyText')n.props.emptyText=value;else n.props.query={...(n.props.query||{}),[key]:value}})},
    addLoopFilter(){const n=this.find(this.selected);if(n?.type!=='query-loop'||!this.loopFilterKey)return;this.commit(()=>{n.props.query={...n.props.query,filters:{...(n.props.query.filters||{}),[this.loopFilterKey]:this.loopFilterValue}}});this.loopFilterKey='';this.loopFilterValue=''},
    removeLoopFilter(key){const n=this.find(this.selected);if(n?.type==='query-loop')this.commit(()=>{delete n.props.query.filters[key]})},
    setShortcode(name){const n=this.find(this.selected);if(n?.type==='shortcode')this.commit(()=>{n.props={name,arguments:{}}})},
    setShortcodeArgument(key,value){const n=this.find(this.selected);if(n?.type==='shortcode')this.commit(()=>{n.props.arguments={...n.props.arguments,[key]:value}})},
    async loadDataCatalog(){this.pickerLoading=true;this.pickerError='';try{const result=await wire.dynamicCatalog();this.sources=result.sources;this.dataFormatters=result.formatters;this.dataComponents=result.components;this.dataSlots=result.slots;this.scriptPermissions=result.scriptPermissions||this.scriptPermissions;this.structureManager=result.structureManager;this.designTokens=result.tokens||{};this.sectionItems=result.sections||[];this.widgetDefinitions=result.widgets||[];for(const def of this.widgetDefinitions)if(!this.widgets.some(w=>w.type===def.type))this.widgets.push({...def,icon:''});this.fonts=result.fonts||[];this.fontDefault=result.fontDefault;this.render()}catch(error){this.pickerError=@js(__('filaforge::studio.picker_failed'))}finally{this.pickerLoading=false}},
    openDataPicker(slot='',replace=false){this.libraryTab='data';this.pickerQuery='';this.pickerSlot=slot;this.pickerTarget=this.selected;this.pickerReplace=replace;this.pickerComponent=null;this.pickerArguments={};this.pickerError='';this.$nextTick(()=>this.$refs.dataPickerSearch?.focus())},
    pickerSources(){const query=this.pickerQuery.trim().toLocaleLowerCase();return this.availableSources().map(source=>({...source,fields:Object.entries(source.fields).filter(([name,field])=>!query||[source.label,field.label,name].some(text=>String(text).toLocaleLowerCase().includes(query)))})).filter(source=>source.fields.length)},
    pickerComponents(){const query=this.pickerQuery.trim().toLocaleLowerCase();return this.dataComponents.filter(item=>!query||[item.label,item.name].some(text=>String(text).toLocaleLowerCase().includes(query)))},
    async chooseDataField(provider,field){if(this.pickerBusy)return;this.pickerError='';if(this.pickerSlot){const node=this.find(this.pickerTarget);if(!node||(this.dataSlots[node.type]||[]).indexOf(this.pickerSlot)<0)return;this.bindingSlot=this.pickerSlot;this.commit(()=>{node.bindings={...(node.bindings||{}),[this.pickerSlot]:{provider,field,formatter:'text',fallback:''}}});this.select(node.id);this.bindingSlot=this.pickerSlot;this.inspectorSections.data=true;this.status=@js(__('filaforge::studio.picker_connected'));return}await this.addPickerElement('field',provider==='@item'?this.rowSource()?.name:provider,field,provider==='@item')},
    chooseDataComponent(component){this.pickerError='';if(component.arguments.length){this.pickerComponent=component;this.pickerArguments={}}else this.addPickerElement('component','',component.name)},
    async addPickerElement(kind,source,name,row=false){if(this.pickerBusy)return;this.pickerBusy=true;this.pickerError='';try{const result=await wire.makeDynamicElement(kind,source,name,kind==='component'?this.pickerArguments:{});if(result.error){this.pickerError=result.error;return}const node=result.node;if(row)Object.values(node.bindings).forEach(binding=>binding.provider='@item');const current=this.find(this.pickerTarget);if(!current){this.pickerError=@js(__('filaforge::studio.picker_failed'));return}if(this.nodes().length>=1000){this.pickerError=@js(__('filaforge::studio.import_limits'));return}if(this.pickerReplace&&kind==='component'&&current.type==='shortcode'){this.commit(()=>{current.props=node.props});this.select(current.id)}else{const parent=this.insertionParent(current.id);if(!parent)return;this.commit(()=>parent.children.push(node));this.select(node.id)}this.inspectorSections.data=true;this.pickerComponent=null;this.status=@js(__('filaforge::studio.picker_added'))}catch(error){this.pickerError=@js(__('filaforge::studio.picker_failed'))}finally{this.pickerBusy=false}},
    nodes(){const all=[];const walk=n=>{all.push(n);n.children.forEach(walk)};walk(this.document.root);return all;},
    find(id){return this.nodes().find(n=>n.id===id)},
    render(){this.port?.postMessage({type:'render',document:this.resolvedCanvasDocument(),selected:this.selected,preview:this.previewMode,fonts:JSON.parse(JSON.stringify(this.fonts)),fontDefault:this.fontDefault,labels:{loop:@js(__('filaforge::studio.data_loop_canvas')),component:@js(__('filaforge::studio.data_component')),wizard:@js(__('filaforge::studio.wizard_preset'))}})},
    flushCanvas(){if(!this.port)return Promise.resolve();return new Promise(resolve=>{const timeout=setTimeout(()=>{this.flushResolve=null;resolve()},1000);this.flushResolve=()=>{clearTimeout(timeout);resolve()};this.port.postMessage({type:'flush'})})},
    async togglePreview(){if(this.previewBusy)return;if(this.previewMode){this.previewMode=false;this.context=null;this.render();return}await this.flushCanvas();this.previewPages={};await this.loadServerPreview()},
    async loadServerPreview(){if(this.previewBusy)return;this.previewBusy=true;try{const result=await wire.previewDocument(JSON.parse(JSON.stringify(this.document)),JSON.parse(JSON.stringify(this.previewPages)));if(result.error){this.status=result.error;return}this.previewMode=true;this.context=null;this.$nextTick(()=>{this.$refs.preview.srcdoc=result.html})}catch(e){this.status=@js(__('filaforge::studio.data_preview_failed'))}finally{this.previewBusy=false}},
    select(id){this.bindingSlot=Object.keys(this.find(id)?.bindings||{})[0]||(this.dataSlots[this.find(id)?.type]||[])[0]||'';this.loopFilterKey='';this.loopFilterValue='';const node=this.find(id);if(!node)return;this.selected=id;this.libraryOpen=false;this.customInspector=!!this.widgetDefinitions.find(w=>w.type===node.type)?.inspector;if(this.customInspector)wire.configureWidget(node.type,JSON.parse(JSON.stringify(node.props))).catch(()=>this.status=@js(__('filaforge::studio.builder.action_failed')));this.draftProps=JSON.parse(JSON.stringify(node.props));this.backgroundHex=/^#[0-9a-f]{6}$/i.test(node.props.tone||'')?node.props.tone:'#4f46e5';this.showInspector=true;this.scriptsOpen=false;if(['progress','wizard','wizard-step','dropdown-menu','menu-item'].includes(node.type))this.inspectorSections.content=true;if(node.type==='shortcode'||node.type==='query-loop')this.inspectorSections.data=true;if(node.type==='heading')wire.set('settings',JSON.parse(JSON.stringify(node.props)),false);this.render()},
