    moveNode(id,targetId,position='inside'){const node=this.find(id),target=this.find(targetId),from=this.parentOf(id);if(!node||!target||!from||id==='root'||id===targetId)return false;const contains=(root,wanted)=>root.children.some(child=>child.id===wanted||contains(child,wanted));if(contains(node,targetId))return false;let edge=position,to;if(edge==='inside'&&(this.acceptsChildren(target)||(node.type==='wizard-step'&&target.type==='wizard')||(node.type==='menu-item'&&['dropdown-menu','menu-item'].includes(target.type))))to=target;else{to=this.parentOf(targetId);if(edge==='inside')edge='after'}if(!to)return false;if((node.type==='menu-item')!==(['dropdown-menu','menu-item'].includes(to.type)))return false;if(from.type==='dropdown-menu'&&from!==to&&from.children.length<=1)return false;if(node.type==='menu-item'&&from!==to&&!this.validMenuTarget(node,to))return false;if((node.type==='wizard-step')!==(to.type==='wizard'))return false;if(from.type==='wizard'&&from!==to&&from.children.length<=1)return false;if(to.type==='wizard'&&from!==to&&to.children.length>=12)return false;const before=edge!=='inside'?targetId:null;this.commit(()=>{from.children.splice(from.children.findIndex(child=>child.id===id),1);if(from.type==='wizard'&&from!==to)from.props.start=Math.min(from.props.start,from.children.length-1);if(edge==='inside')to.children.push(node);else{let index=to.children.findIndex(child=>child.id===before);if(index<0){from.children.push(node);return}if(edge==='after')index++;to.children.splice(index,0,node)}});this.select(id);return true},
    shortcut(e){if(this.previewMode){if(e.key==='Escape')this.togglePreview();return}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();this.save();return}if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||e.target.isContentEditable)return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?this.redo():this.undo()}if(e.key==='Delete'){e.preventDefault();this.remove()}},
    async apply(){if(this.find(this.selected)?.type!=='heading')return;const props=await wire.validatedSettings();this.commit(()=>this.find(this.selected).props=props)},
    undo(){if(!this.past.length)return;this.future.push(JSON.stringify(this.document));this.document=JSON.parse(this.past.pop());this.changed()},
    redo(){if(!this.future.length)return;this.past.push(JSON.stringify(this.document));this.document=JSON.parse(this.future.pop());this.changed()},
    @include('filaforge::editor.authoring-runtime')
    async save(){if(this.busy)return false;clearTimeout(this.autosaveTimer);this.busy=true;await this.flushCanvas();this.flushPageScripts();const snapshot=JSON.stringify(this.document);try{const result=await wire.saveDocument(JSON.parse(snapshot),this.version);if(result.error){this.status=result.error;this.autosavePaused=true;return false}this.version=result.version;this.autosavePaused=false;this.dirty=JSON.stringify(this.document)!==snapshot;this.status=this.dirty?@js(__('filaforge::studio.unsaved')):@js(__('filaforge::studio.saved'));if(!this.dirty)this.discardRecovery();else this.writeRecovery();return !this.dirty}catch(e){this.status=@js(__('filaforge::studio.builder.save_failed'));this.autosavePaused=true;return false}finally{this.busy=false;if(this.dirty&&!this.autosavePaused)this.scheduleAutosave()}},
    async publish(){if(!await this.save())return;this.busy=true;try{const result=await wire.publishDocument(this.version);if(result.error)this.status=result.error;else{this.version=result.version;this.status='Published'}}finally{this.busy=false}}
});
</script>
@endonce
